import { test, expect } from '@playwright/test';

test.describe('Notification Count Reset After Reading All Messages', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should reset notification count to zero after reading all messages', async ({ page }) => {
    // Verify initial notification count is greater than zero
    const notificationBadge = page.getByRole('status', { name: /notifications/i });
    await expect(notificationBadge).toBeVisible();
    const countText = page.getByText(/\d+/);
    await expect(countText).toBeVisible();

    // Verify notification count is displayed
    const count = await countText.textContent();
    expect(parseInt(count)).toBeGreaterThan(0);

    // Read all notifications
    const notificationItems = page.getByRole('listitem');
    const count = await notificationItems.count();
    for (let i = 0; i < count; i++) {
      const item = notificationItems.nth(i);
      const readButton = item.getByRole('button', { name: /read/i });
      await readButton.click();
    }

    // Wait for notification count to reset
    await page.waitForTimeout(500);

    // Verify notification count is reset to zero
    const resetCountText = page.getByText('0');
    await expect(resetCountText).toBeVisible();

    // Verify notification badge is no longer visible or shows zero
    await expect(notificationBadge).toBeVisible();
    await expect(notificationBadge).toContainText('0');
  });

  test('should not reset notification count if not all messages are read', async ({ page }) => {
    // Verify initial notification count is greater than zero
    const notificationBadge = page.getByRole('status', { name: /notifications/i });
    await expect(notificationBadge).toBeVisible();
    const countText = page.getByText(/\d+/);
    await expect(countText).toBeVisible();

    // Verify notification count is displayed
    const count = await countText.textContent();
    expect(parseInt(count)).toBeGreaterThan(0);

    // Read only some notifications
    const notificationItems = page.getByRole('listitem');
    const totalCount = await notificationItems.count();
    const readCount = Math.floor(totalCount / 2);

    for (let i = 0; i < readCount; i++) {
      const item = notificationItems.nth(i);
      const readButton = item.getByRole('button', { name: /read/i });
      await readButton.click();
    }

    // Wait for API response
    await page.waitForTimeout(500);

    // Verify notification count is not reset to zero
    const remainingCountText = page.getByText(/\d+/);
    await expect(remainingCountText).toBeVisible();

    const remainingCount = await remainingCountText.textContent();
    expect(parseInt(remainingCount)).toBeGreaterThan(0);

    // Verify notification badge still shows remaining count
    await expect(notificationBadge).toContainText(remainingCount);
  });
});
